"""Vendor treasures (addon/Glide/Data/VendorTreasures.lua, generated by tools/build_vendor_treasures.py from RestedXP's
copy of Cpt. Stadics' Vendor Treasures, CC BY-NC 3.0): vendors with limited-stock gear and potions worth buying.
The addon reports which one the player is near by its 1-based index in that file, so the index is looked up in the copy
the game loads: the installed addon's (<wow_dir>/Interface/AddOns/Glide, as companion/versions.py finds it), and the
project's own copy only when there is no installed one (no WoW folder set, no addon there). An installed copy older or
newer than the project's would otherwise name the wrong vendor."""
import json
import os
import re

import glideconfig

ROOT = os.path.normpath(os.path.join(os.path.dirname(os.path.abspath(__file__)), ".."))
PATH = os.path.join(ROOT, "addon", "Glide", "Data", "VendorTreasures.lua")
_ENTRY = re.compile(r"\{\s*(\d+),\s*([\d.]+),\s*([\d.]+),\s*(\"(?:[^\"\\]|\\.)*\"),\s*\"(\w)\",\s*\"(\w)\",\s*\{([^}]*)\}")
_cache = {}


def load(path=None):
    """[{"map", "x", "y", "name", "kind" G|P, "faction" A|H|N, "items"}] in file order ([] without the file)."""
    path = path or PATH
    try:
        mt = os.path.getmtime(path)
    except OSError:
        return []
    hit = _cache.get(path)
    if hit and hit[0] == mt:
        return hit[1]
    with open(path, encoding="utf-8") as fh:
        text = fh.read()
    out = [{"map": int(m.group(1)), "x": float(m.group(2)), "y": float(m.group(3)), "name": json.loads(m.group(4)),
            "kind": m.group(5), "faction": m.group(6), "items": [int(i) for i in re.findall(r"\d+", m.group(7))]}
           for m in _ENTRY.finditer(text)]
    _cache[path] = (mt, out)
    return out


def installed_path(wow_dir=None):
    """The installed addon's VendorTreasures.lua (None without a WoW folder; the file may not be there)."""
    wow_dir = wow_dir or glideconfig.wow_dir(ROOT)
    return os.path.join(wow_dir, "Interface", "AddOns", "Glide", "Data", "VendorTreasures.lua") if wow_dir else None


def vendors(wow_dir=None):
    """The table the game's addon numbers its vendors by: the installed copy's, else the project's (load())."""
    p = installed_path(wow_dir)
    return (load(p) if p else None) or load()


def vendor(index, wow_dir=None):
    """The vendor at the addon's 1-based index, or None."""
    v = vendors(wow_dir)
    return v[index - 1] if isinstance(index, int) and 1 <= index <= len(v) else None
